import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.xwas.StratifiedLdsc;
import static org.jlinalg.cli.LdscToolsCli.*;

/** Captured prepared-data workflow for the native partitioned Hsq/overlap API. */
public final class StratifiedLdscCli {
    static final String PROFILE="native-partitioned-ldsc-cbiit302-fixed-initial-v1";
    static final String SCOPE="Prepared observed-scale partitioned Hsq, using selected CBIIT 3.0.2 fixed initial weights (old_weights=True), joint full/delete fits and explicit optional binary-annotation overlap summaries. Reference commit 6c673952cee74bd5c57aef1555a03b1c015399a0. No automatic SNP/annotation removal, deduplication, munging, allele/reference alignment, annotation/LD generation, liability conversion, historical-edition parity or whole-paper reproduction. The caller declares complete prepared rows, reference counts, genome order and annotation provenance. No Python/R runtime or external LDSC installation needed.";
    static final String ACTION="Require exit 0, COMPLETED.json and analysis.json result_admitted=true. SKIP3 means dependent analysis skipped for a missing/forbidden prerequisite, unavailable Java dependency or unsupported requested method. Supply the named permitted resource or separately qualified method and retry NEW output. FAIL2 means no complete result admitted: retain exact inputs and partial output, read FAILURE.txt/WARNINGS.md, correct the named input, rank, reference, block, capacity or numerical issue and retry NEW output. Never remove failed SNPs/annotations/blocks, force positive heritability, replace NA/NaN, clamp final estimates or substitute a pseudoinverse to obtain success. Binary overlap counts and the unique universe must describe the same reference population/columns as the LD scores. Study-specific sidedness and multiple-testing families require separate explicit choices.";
    private record Input(List<String> variants,double[] chi,double[] weight,double[] n,double[][] ld,boolean bom) { }
    private static final class Skipped extends IOException {private static final long serialVersionUID=1L;Skipped(String why){super(why);}Skipped(String why,Throwable cause){super(why,cause);}}
    private StratifiedLdscCli(){ }
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    public static int run(String[] args,PrintStream output,PrintStream error) {
        Path owned=null;
        try {
            if(args.length==0||args.length==1&&args[0].equals("--help")) {
                output.println("java -cp OMICSMATIC_JAR org.jlinalg.cli.StratifiedLdscCli --request UTF8_JSON\nRequired request: schema_version=1,analysis=partitioned-hsq,weighting=source-fixed-initial,input,out NEW,annotations (ordered unique labels),annotation_counts (matching positive reference counts),n_blocks,intercept (number or string free),overlap (binary intersection TSV path or null),reference_universe_variants (positive number with overlap, otherwise null),data_provenance,row_order_declaration,annotation_provenance. Every key is explicit; no inferred defaults.\nInput literal TSV header: variant<TAB>chi_square<TAB>weight_ld_score<TAB>n<TAB>ANNOTATION1<TAB>ANNOTATION2... in declared order. Overlap header: annotation<TAB>ANNOTATION1<TAB>ANNOTATION2...; matching row labels in the same order. Blank, duplicate, incomplete, nonfinite and extra fields are refused, with no repair/join/filtering. UTF-8 BOM is recorded. Paths resolve against the request.\nWhole-input limit: 64 MiB per table, 2 million rows, 256 annotations, 10000 blocks; further complete matrix/operation limits are in the API guide. Outputs: exact source request/input/overlap, model.json, coefficients.tsv, optional overlap-summary.tsv, row-audit.tsv, warnings, manifest and checked completion. Full/delete coefficients, covariance, ratio jackknife and fixed initial weights are retained in model.json.\n"+SCOPE+"\n"+ACTION);output.flush();return output.checkError()?2:0;
            }
            require(args.length==2&&args[0].equals("--request"),"Use --request JSON or --help");
            Path request=regular(Path.of(args[1]));var requestPin=NextflowFiles.pin(request,1048576,()->{});byte[] requestBytes=NextflowFiles.bytes(request,1048576);require(requestPin.equals(pin(requestBytes)),"Request changed during capture");
            Map<?,?> m=NextflowFiles.object(NextflowParameters.parse(NextflowFiles.utf8(requestBytes),1048576,100000));
            NextflowFiles.keys(m,"schema_version","analysis","weighting","input","out","annotations","annotation_counts","n_blocks","intercept","overlap","reference_universe_variants","data_provenance","row_order_declaration","annotation_provenance");NextflowFiles.integer(m.get("schema_version"),1,1);
            String analysis=NextflowFiles.text(m.get("analysis")),weighting=NextflowFiles.text(m.get("weighting"));
            if(!analysis.equals("partitioned-hsq")||!weighting.equals("source-fixed-initial"))throw new Skipped("Requested analysis/weighting is unsupported: "+analysis+" / "+weighting+". No estimator substitution.");
            String provenance=label(NextflowFiles.text(m.get("data_provenance"))),order=label(NextflowFiles.text(m.get("row_order_declaration"))),annotationProvenance=label(NextflowFiles.text(m.get("annotation_provenance")));
            var annotations=new ArrayList<String>();var names=new HashSet<String>();for(Object value:NextflowFiles.list(m.get("annotations"))){String name=label(NextflowFiles.text(value));require(names.add(name)&&!Set.of("variant","chi_square","weight_ld_score","n","annotation").contains(name),"Unique annotation labels distinct from reserved input headers required");annotations.add(name);}
            require(annotations.size()>=2&&annotations.size()<=StratifiedLdsc.MAXIMUM_ANNOTATIONS,"Declare 2..256 ordered annotations");List<?> declaredCounts=NextflowFiles.list(m.get("annotation_counts"));require(declaredCounts.size()==annotations.size(),"Each annotation needs its own reference count");double[] counts=new double[declaredCounts.size()];for(int i=0;i<counts.length;i++){counts[i]=number(declaredCounts.get(i));require(counts[i]>0,"Positive reference annotation counts required");}
            int blocks=(int)NextflowFiles.integer(m.get("n_blocks"),2,10000);Object setting=m.get("intercept");Double fixed=setting instanceof String s&&s.equals("free")?null:number(setting);
            Path input=regular(resolve(request.getParent(),m.get("input"))),overlap=m.get("overlap")==null?null:regular(resolve(request.getParent(),m.get("overlap")));Double universe=m.get("reference_universe_variants")==null?null:number(m.get("reference_universe_variants"));
            require((overlap==null)==(universe==null)&&(universe==null||universe>0),"Declare overlap and positive unique reference-universe count together, or both null");
            if(overlap!=null)require(universe==Math.rint(universe)&&Arrays.stream(counts).allMatch(v->v==Math.rint(v)),"Binary overlap mode requires integer reference annotation/universe counts; continuous-annotation overlap requires a separate declared model");
            var protectedPaths=new ArrayList<Path>(List.of(request,input));if(overlap!=null)protectedPaths.add(overlap);Path dest=destination(resolve(request.getParent(),m.get("out")),protectedPaths);Files.createDirectories(dest.getParent());Files.createDirectory(dest);owned=dest;
            write(owned.resolve("WARNINGS.md"),"# Stratified LDSC: scope and required actions\n\n"+SCOPE+"\n\n**REQUIRED ACTIONS:** "+ACTION+"\n\nConsecutive-row jackknife inference depends on the declared genome order/reference population. M_j*tau_j are coefficient allocations; use the separate overlap summary for overlapping categories. Baseline/zero-contrast enrichment P values remain NA. No outer multiple-testing correction is inferred. The prepared model does not apply the original wrapper's raw-data filtering defaults.\n");
            Files.write(owned.resolve("source-request.json"),requestBytes,StandardOpenOption.CREATE_NEW);var inputPin=NextflowFiles.pin(input,MAX_BYTES,()->{});byte[] inputBytes=NextflowFiles.bytes(input,MAX_BYTES);require(inputPin.equals(pin(inputBytes)),"Input changed during capture");Files.write(owned.resolve("source-input.tsv"),inputBytes,StandardOpenOption.CREATE_NEW);
            byte[] overlapBytes=null;NextflowFiles.Pin overlapPin=null;if(overlap!=null){overlapPin=NextflowFiles.pin(overlap,MAX_BYTES,()->{});overlapBytes=NextflowFiles.bytes(overlap,MAX_BYTES);require(overlapPin.equals(pin(overlapBytes)),"Overlap input changed during capture");Files.write(owned.resolve("source-overlap.tsv"),overlapBytes,StandardOpenOption.CREATE_NEW);}
            Input data=read(inputBytes,annotations);require(!Thread.currentThread().isInterrupted(),"Analysis interrupted before fitting; no result admitted");
            var fit=StratifiedLdsc.fit(data.chi(),data.ld(),data.weight(),data.n(),counts,blocks,fixed);var fitted=new LinkedHashMap<String,Object>();fitted.put("profile",PROFILE);fitted.put("component_only",true);fitted.put("complete_analysis_admitted",false);fitted.put("annotations",annotations);fitted.put("fit",record(fit));NextflowFiles.writeJson(owned.resolve("component-model.json"),fitted);
            StratifiedLdsc.Overlap summary=null;boolean overlapBom=false;if(overlapBytes!=null){String text=NextflowFiles.utf8(overlapBytes);overlapBom=text.startsWith("\ufeff");summary=StratifiedLdsc.overlap(fit,readOverlap(text,annotations),universe);}
            var model=new LinkedHashMap<String,Object>();model.put("profile",PROFILE);model.put("annotations",annotations);model.put("fit",record(fit));model.put("overlap",summary==null?null:record(summary));model.put("reference_universe_variants",universe);NextflowFiles.writeJson(owned.resolve("model.json"),model);
            double[] estimate=fit.estimates();double[][] covariance=fit.covariance();var coefficients=new StringBuilder("annotation\tcoefficient\tcoefficient_se\tcoefficient_allocation\n");double[] allocations=fit.allocations();for(int j=0;j<annotations.size();j++)coefficients.append(annotations.get(j)).append('\t').append(estimate[j]).append('\t').append(Math.sqrt(covariance[j][j])).append('\t').append(allocations[j]).append('\n');write(owned.resolve("coefficients.tsv"),coefficients.toString());
            if(summary!=null)writeOverlap(owned.resolve("overlap-summary.tsv"),annotations,summary);
            var rowAudit=new StringBuilder("row_index\tvariant\tfixed_initial_precision_weight\n");double[] weights=fit.weights();for(int i=0;i<weights.length;i++)rowAudit.append(i).append('\t').append(data.variants().get(i)).append('\t').append(weights[i]).append('\n');write(owned.resolve("row-audit.tsv"),rowAudit.toString());
            Files.writeString(owned.resolve("WARNINGS.md"),"\n## Observed model warnings\n\n"+String.join("\n\n",fit.warnings())+"\n",StandardCharsets.UTF_8,StandardOpenOption.APPEND);
            var report=new LinkedHashMap<String,Object>();report.put("profile",PROFILE);report.put("result_admitted",true);report.put("rows",fit.rows());report.put("blocks",fit.blocks());report.put("annotations",annotations);report.put("data_provenance",provenance);report.put("row_order_declaration",order);report.put("annotation_provenance",annotationProvenance);report.put("input_utf8_bom_present",data.bom());report.put("overlap_utf8_bom_present",overlapBom);report.put("overlap_summary_requested",overlap!=null);report.put("observed_warnings",fit.warnings());report.put("whole_tool_qualified",false);report.put("whole_goal_complete",false);
            require(!Thread.currentThread().isInterrupted(),"Analysis interrupted; no result admitted");require(requestPin.equals(NextflowFiles.pin(request,1048576,()->{}))&&requestPin.equals(NextflowFiles.pin(owned.resolve("source-request.json"),1048576,()->{})),"Original/captured request changed");require(inputPin.equals(NextflowFiles.pin(input,MAX_BYTES,()->{}))&&inputPin.equals(NextflowFiles.pin(owned.resolve("source-input.tsv"),MAX_BYTES,()->{})),"Original/captured input changed");if(overlap!=null)require(overlapPin.equals(NextflowFiles.pin(overlap,MAX_BYTES,()->{}))&&overlapPin.equals(NextflowFiles.pin(owned.resolve("source-overlap.tsv"),MAX_BYTES,()->{})),"Original/captured overlap changed");NextflowFiles.writeJson(owned.resolve("analysis.json"),report);
            var manifest=new TreeMap<String,Object>();try(var files=Files.walk(owned)){for(Path p:files.filter(Files::isRegularFile).sorted().toList())manifest.put(owned.relativize(p).toString().replace('\\','/'),NextflowFiles.pin(p,256L<<20,()->{}));}NextflowFiles.writeJson(owned.resolve("manifest.json"),manifest);
            output.println("PASS native partitioned LDSC: "+fit.rows()+" rows, "+annotations.size()+" annotations, "+blocks+" blocks. READ "+owned.resolve("WARNINGS.md"));output.flush();error.flush();require(!output.checkError()&&!error.checkError(),"Console recording failed; no result admitted");NextflowFiles.writeJson(owned.resolve("COMPLETED.json"),Map.of("status","PASS_NATIVE_PARTITIONED_LDSC","profile",PROFILE,"manifest",NextflowFiles.pin(owned.resolve("manifest.json"),1048576,()->{})));return 0;
        }catch(Exception e){return failed(owned,e,error);}
         catch(LinkageError e){return failed(owned,new Skipped("Required Java class/runtime unavailable; use the complete current source-build JAR and Java 17+: "+e,e),error);}
         catch(OutOfMemoryError e){return failed(owned,new IOException("Heap exhausted; retain inputs and retry NEW output with sufficient resources; no complete result",e),error);}
    }
    private static Input read(byte[] bytes,List<String> names)throws IOException {
        String text=NextflowFiles.utf8(bytes);boolean bom=text.startsWith("\ufeff");if(bom)text=text.substring(1);var variants=new ArrayList<String>();var seen=new HashSet<String>();var values=new ArrayList<double[]>();
        try(var lines=text.lines()){var it=lines.iterator();require(it.hasNext()&&it.next().equals("variant\tchi_square\tweight_ld_score\tn\t"+String.join("\t",names)),"Exact literal input header and annotation order required");while(it.hasNext()){String[] fields=it.next().split("\t",-1);require(fields.length==names.size()+4,"Each row needs every declared field; blank/extra fields are not filtered");String variant=label(fields[0]);require(seen.add(variant),"Duplicate literal variant ID; no deduplication or join");variants.add(variant);require(variants.size()<=2_000_000&&(long)variants.size()*names.size()<=StratifiedLdsc.MAXIMUM_DESIGN_CELLS,"Complete input exceeds row/design capacity; no truncation");double[] row=new double[names.size()+3];for(int j=1;j<fields.length;j++)row[j-1]=decimal(fields[j]);values.add(row);}}
        int n=values.size();double[] y=new double[n],w=new double[n],ns=new double[n];double[][] ld=new double[n][names.size()];for(int i=0;i<n;i++){double[] row=values.get(i);y[i]=row[0];w[i]=row[1];ns[i]=row[2];System.arraycopy(row,3,ld[i],0,names.size());}return new Input(List.copyOf(variants),y,w,ns,ld,bom);
    }
    private static double[][] readOverlap(String text,List<String> names)throws IOException {
        if(text.startsWith("\ufeff"))text=text.substring(1);var rows=text.lines().iterator();require(rows.hasNext()&&rows.next().equals("annotation\t"+String.join("\t",names)),"Exact overlap annotation header/order required");double[][] matrix=new double[names.size()][names.size()];
        for(int i=0;i<names.size();i++){require(rows.hasNext(),"Every overlap row required");String[] fields=rows.next().split("\t",-1);require(fields.length==names.size()+1&&fields[0].equals(names.get(i)),"Exact overlap row label/order and all fields required; no inferred join");for(int j=0;j<names.size();j++){matrix[i][j]=decimal(fields[j+1]);require(matrix[i][j]==Math.rint(matrix[i][j]),"Binary overlap intersections must be integer counts; no rounding or continuous-model substitution");}}require(!rows.hasNext(),"Extra/blank overlap rows are not discarded");return matrix;
    }
    private static Map<String,Object> record(Record value)throws ReflectiveOperationException,IOException {
        require(value instanceof StratifiedLdsc.Result||value instanceof StratifiedLdsc.Overlap,"Owned scientific result required");var map=new LinkedHashMap<String,Object>();
        for(var field:value.getClass().getRecordComponents()){Object item=field.getAccessor().invoke(value);if(field.getName().equals("enrichmentLogPValues")){double[] logs=(double[])item;Object[] encoded=new Object[logs.length];Double[] probabilities=((StratifiedLdsc.Overlap)value).enrichmentPValues();for(int i=0;i<logs.length;i++){if(Double.isNaN(logs[i])){require(probabilities[i]==null,"Only an undefined enrichment test may have NA log-P");encoded[i]="NA";}else encoded[i]=logs[i];}item=encoded;}map.put(field.getName(),item);}return map;
    }
    private static void writeOverlap(Path path,List<String> names,StratifiedLdsc.Overlap summary)throws IOException {
        var table=new StringBuilder("annotation\tproportion_snps\tproportion_h2\tproportion_h2_se\tenrichment\tenrichment_se\tenrichment_p\tenrichment_log_p\tcoefficient\tcoefficient_se\tcoefficient_z\n");double[] mp=summary.snpProportions(),hp=summary.h2Proportions(),hs=summary.h2ProportionStandardErrors(),e=summary.enrichments(),es=summary.enrichmentStandardErrors(),lp=summary.enrichmentLogPValues(),coef=summary.coefficients(),se=summary.coefficientStandardErrors(),z=summary.coefficientZScores();Double[] p=summary.enrichmentPValues();
        for(int i=0;i<names.size();i++)table.append(names.get(i)).append('\t').append(mp[i]).append('\t').append(hp[i]).append('\t').append(hs[i]).append('\t').append(e[i]).append('\t').append(es[i]).append('\t').append(p[i]==null?"NA":p[i]).append('\t').append(p[i]==null?"NA":lp[i]).append('\t').append(coef[i]).append('\t').append(se[i]).append('\t').append(z[i]).append('\n');write(path,table.toString());
    }
    private static int failed(Path owned,Exception cause,PrintStream error) {
        int code=cause instanceof Skipped||cause instanceof NoSuchFileException||cause instanceof AccessDeniedException||cause instanceof SecurityException?3:2;String status=code==3?"SKIP3_DEPENDENT_ANALYSIS_SKIPPED":"FAIL2_NO_RESULT_ADMITTED",message=status+": "+cause+"\nREQUIRED ACTIONS: "+ACTION+"\n";
        if(owned!=null)try{Files.deleteIfExists(owned.resolve("COMPLETED.json"));if(Files.exists(owned.resolve("analysis.json")))Files.move(owned.resolve("analysis.json"),owned.resolve("unadmitted-analysis.json"));NextflowFiles.writeJson(owned.resolve("analysis.json"),Map.of("profile",PROFILE,"result_admitted",false,"status",status,"cause",cause.toString(),"required_actions",ACTION));write(owned.resolve("FAILURE.txt"),message);Files.writeString(owned.resolve("WARNINGS.md"),"\n## "+status+"\n\n"+message,StandardCharsets.UTF_8,StandardOpenOption.APPEND);}catch(IOException recording){message+="Failure recording also failed: "+recording+"\n";}
        error.print(message);error.flush();return code;
    }
}
